UPDATE t_board
SET board_title = #{boardTitle}, board_contents = #{boardContents}, board_update_id = #{boardUpdateId}, board_update_date = NOW()
WHERE board_idx = #{boardIdx}

UPDATE t_board
SET deleted_yn = 'Y'
WHERE board_idx = #{boardIdx}

UPDATE t_board
SET board_hit_cnt = board_hit_cnt + 1
WHERE board_idx = #{boardIdx}
